<script setup>
import DeliveryWindow from '../../Components/DeliveryWindow.vue';
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import Dialog from '../../Components/Shared/Dialog.vue';
import { cartKey, readCart, cartLine, choicesValid, money } from '../../Support/cart.js';
import { Head, Link, usePage } from '@inertiajs/vue3';
const page = usePage();
const props = defineProps({ store: Object, period: Object, items: Array, catalogUrl: String, serverNow: String, checkoutUrl: String });
const offset = Date.parse(props.serverNow) - Date.now();
const now = ref(Date.now() + offset); let timer; onMounted(() => { timer = setInterval(() => { now.value = Date.now() + offset; }, 1000); }); onBeforeUnmount(() => clearInterval(timer));
const status = computed(() => {
    if (!props.period) return 'none';
    if (props.period.status === 'closed' || props.period.status === 'ended') return 'closed';
    if (now.value >= Date.parse(props.period.closesAt)) return 'closed';
    return now.value < Date.parse(props.period.opensAt) ? 'scheduled' : 'open';
});
const countdown = computed(() => {
    if (!props.period || status.value === 'closed') return [];
    const end = Date.parse(status.value === 'scheduled' ? props.period.opensAt : props.period.closesAt);
    const seconds = Math.max(0, Math.floor((end - now.value) / 1000));
    const days = Math.floor(seconds / 86400);
    return [...(days ? [{ label: 'Days', value: String(days).padStart(2, '0') }] : []),
        { label: 'Hours', value: String(Math.floor(seconds % 86400 / 3600)).padStart(2, '0') },
        { label: 'Minutes', value: String(Math.floor(seconds % 3600 / 60)).padStart(2, '0') },
        { label: 'Seconds', value: String(seconds % 60).padStart(2, '0') }];
});
const date = value => new Intl.DateTimeFormat('en-GB', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Asia/Jakarta' }).format(new Date(value));
const cart = ref([]); const active = ref(null); const selected = ref([]); const quantity = ref(1); const error = ref(''); const storageError = ref('');
onMounted(() => { if (props.period) cart.value = readCart(props.period.id); });
watch(cart, value => { try { sessionStorage.setItem(cartKey(props.period.id), JSON.stringify(value)); } catch { storageError.value = 'Browser storage is unavailable. Enable storage to continue to checkout.'; } }, { deep: true });
const count = computed(() => cart.value.reduce((sum, line) => sum + line.quantity, 0));
const cartRows = computed(() => cart.value.map((line, index) => { const row = cartLine(line, props.items); return row ? { ...row, index } : null; }).filter(Boolean));
const total = computed(() => cart.value.reduce((sum, line) => sum + (cartLine(line, props.items)?.total || 0), 0));
const chosenPrice = computed(() => active.value ? cartLine({ id: active.value.id, quantity: quantity.value, choices: selected.value }, props.items)?.total : 0);
const select = item => { active.value = item; selected.value = []; quantity.value = 1; error.value = ''; };
const toggle = (group, id) => { if (group.selection === 'single') selected.value = [...selected.value.filter(value => !group.choices.some(choice => choice.id === value)), id]; else selected.value = selected.value.includes(id) ? selected.value.filter(value => value !== id) : [...selected.value, id]; };
const add = () => {
    if (!choicesValid(active.value, selected.value)) { error.value = 'Please complete the required choices.'; return; }
    const qty = Number(quantity.value); const used = cart.value.filter(line => line.id === active.value.id).reduce((sum,line) => sum + line.quantity, 0);
    if (!Number.isInteger(qty) || qty < 1 || qty > 99 || (active.value.remaining !== null && used + qty > active.value.remaining)) { error.value = 'This quantity exceeds the available session quota.'; return; }
    const choices = [...selected.value].sort(); const existing = cart.value.find(line => line.id === active.value.id && JSON.stringify([...line.choices].sort()) === JSON.stringify(choices));
    if (existing && existing.quantity + qty > 99) { error.value = 'Maximum 99 per selection.'; return; }
    if (!existing && cart.value.length >= 50) { error.value = 'Maximum 50 selections per order.'; return; }
    if (existing) existing.quantity += qty; else cart.value.push({ id: active.value.id, quantity: qty, choices });
    active.value = null;
};
</script>
<template>
    <Head :title="`${store.name} — Open Order`" /><div class="min-h-screen bg-[#f5f2ec] text-[#504941]"><header class="border-b border-stone-200 bg-[#fffdf9]"><div class="mx-auto flex min-h-20 max-w-6xl items-center px-5 text-xl font-medium sm:px-8"><span>{{ store.name }}</span><Link :href="page.props.navigation.myOrders" class="ml-auto rounded-full border border-stone-300 px-4 py-2 text-sm font-medium">My orders</Link></div></header><main class="mx-auto max-w-6xl px-5 py-10 sm:px-8"><nav class="flex gap-3 text-sm"><Link :href="catalogUrl" class="rounded-full border border-stone-300 px-5 py-3">Our Products</Link><span class="rounded-full bg-[#504941] px-5 py-3 text-white">Open Order</span></nav>
        <section class="mt-8 overflow-hidden rounded-3xl border border-stone-200 bg-[#fffdf9]"><div class="grid lg:grid-cols-[1fr_auto]"><div class="p-6 sm:p-8"><span class="inline-flex items-center gap-2 rounded-full px-3 py-1.5 text-xs font-medium" :class="status === 'open' ? 'bg-[#edf2e7] text-[#60734c]' : 'bg-stone-100 text-stone-600'"><span v-if="status === 'open'" class="size-1.5 rounded-full bg-[#7b8967]"/>{{ status === 'open' ? 'Open now' : status === 'scheduled' ? 'Coming soon' : status === 'closed' ? 'Session closed' : 'No session yet' }}</span><h1 class="mt-4 text-3xl font-semibold tracking-tight sm:text-4xl">{{ period?.name || 'Open Order' }}</h1><template v-if="period"><div class="mt-6 flex items-start gap-3"><svg aria-hidden="true" class="mt-0.5 size-5 shrink-0 text-stone-400" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg><div class="text-sm leading-6"><p><span class="text-stone-400">Opens</span> {{ date(period.opensAt) }}</p><p><span class="text-stone-400">Closes</span> {{ date(period.closesAt) }} · WIB</p></div></div><div class="mt-5 flex flex-wrap gap-2"><span v-if="period.pickup" class="rounded-full border border-stone-200 px-3 py-1.5 text-xs text-stone-500">Pickup</span><span v-if="period.delivery" class="rounded-full border border-stone-200 px-3 py-1.5 text-xs text-stone-500">Delivery</span></div></template></div><div v-if="countdown.length" class="flex flex-col justify-center bg-[#504941] p-6 text-white sm:p-8"><p class="mb-5 text-xs font-medium uppercase tracking-[.18em] text-white/60">{{ status === 'scheduled' ? 'Ordering opens in' : 'Ordering closes in' }}</p><div role="timer" aria-label="Session countdown" aria-live="off" class="flex gap-2 sm:gap-3"><div v-for="part in countdown" :key="part.label" class="min-w-12 rounded-2xl border border-white/10 bg-white/[.08] px-2 py-4 text-center sm:min-w-20 sm:px-4"><span class="block text-3xl font-semibold tracking-tight tabular-nums sm:text-4xl">{{ part.value }}</span><span class="mt-2 block text-[10px] uppercase tracking-widest text-white/50">{{ part.label }}</span></div></div><p class="mt-5 text-xs text-white/50">{{ status === 'scheduled' ? 'Get ready to choose your favorites.' : 'Choose your favorites before the session ends.' }}</p></div></div></section>

        <DeliveryWindow v-if="period?.delivery" :window="period.deliveryWindow" class="mt-5"/><div v-if="status === 'open' || status === 'scheduled'" class="mt-6 grid gap-5 sm:grid-cols-2 lg:grid-cols-3"><article v-for="item in items" :key="item.id" class="flex flex-col overflow-hidden rounded-3xl border border-stone-200 bg-[#fffdf9] transition-shadow hover:shadow-md"><img v-if="item.imageUrl" :src="item.imageUrl" :alt="item.name" loading="lazy" class="aspect-[4/3] w-full object-cover"/><div v-else class="flex aspect-[4/3] items-center justify-center bg-[#eae5dc] text-sm text-stone-500">{{ item.name }}</div><div class="flex flex-1 flex-col gap-3 p-6"><h2 class="text-xl font-semibold">{{ item.name }}</h2><p v-if="item.ratingCount" class="text-sm text-amber-700">★ {{ item.rating }} <span class="text-stone-500">({{ item.ratingCount }})</span></p><p v-if="item.description" class="line-clamp-3 text-sm leading-7 text-stone-500">{{ item.description }}</p><div class="mt-auto flex items-center justify-between gap-3 pt-3"><span class="text-lg font-semibold">{{ money(item.price) }}</span><span v-if="item.remaining !== null" class="text-xs text-stone-500">{{ item.remaining }} left</span></div><button type="button" :disabled="status !== 'open' || item.remaining === 0" class="rounded-full bg-[#504941] px-5 py-3 text-sm font-medium text-white transition-colors hover:bg-stone-700 disabled:opacity-40" @click="select(item)">{{ item.remaining === 0 ? 'Sold out' : status === 'scheduled' ? 'Coming soon' : '+ Select' }}</button></div></article></div>
        <p v-if="storageError" role="alert" class="mt-4 text-sm text-red-700">{{ storageError }}</p>
        <section v-if="count" class="mt-8 rounded-3xl border border-stone-200 bg-[#fffdf9] p-6"><div class="flex flex-wrap justify-between gap-3"><h2 class="text-xl font-semibold">Your order · {{ count }} items</h2><span class="text-xs text-stone-500">Keep adding products before checkout</span></div><article v-for="line in cartRows" :key="line.index" class="flex items-center gap-4 border-b border-stone-100 py-4 last:border-0"><img v-if="line.item.imageUrl" :src="line.item.imageUrl" :alt="line.item.name" class="size-14 rounded-xl object-cover"/><div class="min-w-0 flex-1"><p class="text-sm font-semibold">{{ line.quantity }} × {{ line.item.name }}</p><p class="mt-1 text-xs text-stone-500">{{ line.selected.map(choice => choice.name).join(' · ') }}</p></div><span class="text-sm font-medium">{{ money(line.total) }}</span><button type="button" :aria-label="`Remove ${line.item.name} from order`" class="flex size-8 shrink-0 items-center justify-center rounded-full border border-stone-200 text-lg text-stone-500 hover:bg-red-50 hover:text-red-700" @click="cart.splice(line.index, 1)">×</button></article></section><div v-if="count && status === 'open'" class="sticky bottom-4 mt-8 flex flex-wrap items-center justify-between gap-4 rounded-2xl bg-[#504941] px-6 py-4 text-white shadow-xl"><div><p class="text-sm">{{ count }} items in your order</p><p class="mt-1 text-lg font-semibold">{{ money(total) }}</p></div><Link v-if="!storageError" :href="checkoutUrl" class="rounded-full bg-white px-6 py-3 text-sm font-semibold text-[#504941]">Review &amp; checkout →</Link></div>
    </main><Dialog :open="Boolean(active)" :title="active?.name" @close="active = null"><template v-if="active"><img v-if="active.imageUrl" :src="active.imageUrl" :alt="active.name" class="mb-5 aspect-[2/1] w-full rounded-2xl object-cover"/><fieldset v-for="group in active.options" :key="group.id" class="mb-5"><legend class="mb-3 text-sm font-semibold">{{ group.name }} <span class="font-normal text-stone-400">{{ group.required ? '· Required' : '· Optional' }}</span></legend><label v-for="choice in group.choices" :key="choice.id" class="mb-2 flex cursor-pointer items-center justify-between gap-3 rounded-xl border border-stone-200 px-4 py-3 text-sm" :class="selected.includes(choice.id) ? 'bg-stone-100 border-stone-500' : ''"><span class="flex items-center gap-3"><input :type="group.selection === 'single' ? 'radio' : 'checkbox'" :name="group.id" :checked="selected.includes(choice.id)" class="accent-stone-700" @change="toggle(group, choice.id)"/>{{ choice.name }}</span><span>{{ choice.price_adjustment ? '+' + money(choice.price_adjustment) : 'Included' }}</span></label><button v-if="!group.required && group.selection === 'single'" type="button" class="text-xs text-stone-500 underline" @click="selected = selected.filter(id => !group.choices.some(choice => choice.id === id))">Clear selection</button></fieldset><p class="mb-4 flex items-center justify-between border-t border-stone-100 pt-4 text-sm"><span>Price per item with choices</span><strong>{{ money(quantity > 0 ? chosenPrice / quantity : active.price) }}</strong></p><label class="flex items-center justify-between gap-4 text-sm">Quantity<input v-model.number="quantity" type="number" min="1" max="99" class="w-24 rounded-xl border border-stone-300 px-3 py-2"/></label><p v-if="error" role="alert" class="mt-4 text-sm text-red-700">{{ error }}</p><button type="button" class="mt-6 flex w-full justify-between rounded-full bg-[#504941] px-5 py-3 text-sm font-medium text-white" @click="add"><span>Add to order</span><span>{{ money(chosenPrice) }}</span></button></template></Dialog></div>
</template>
